def insert_fag(conn, question, answer, embedding):
    vector_str = f"[{', '.join(map(str, embedding))}]"
    conn.execute(
        text(
            """
            INSERT INTO fag (id, question, answer, embedding)
            VALUES (
            :id,
            :question,
            :answer,
            :embedding
            )
            """,
        ),
        {"id": uuid4(), "question": question, "answer": answer, "embedding": vector_str},
    )


